43	// --- REGISTRATION (Multi-Level Security Gate) ---
44	router.post("/register", async (req, res) => {
45	    const { recaptchaToken, ...userData } = req.body;
46	    try {
47	        if (!recaptchaToken) return res.status(400).json({ errors: ["Security token missing."] });
48	
49	        // 1. reCAPTCHA Verification
50	        const params = new URLSearchParams();
51	        params.append('secret', process.env.RECAPTCHA_SECRET_KEY);
52	        params.append('response', recaptchaToken);
53	
54	        const googleResponse = await axios.post('https://www.google.com/recaptcha/api/siteverify', params, {
55	            headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
56	        });
57	
58	        if (!googleResponse.data.success || googleResponse.data.score < 0.5) {
59	            return res.status(403).json({ errors: ["Security check failed. Please try again."] });
60	        }
61	
62	        // 2. Data Validation
63	        let validationSchema = yup.object({
64	            name: yup.string().trim().required("Full name is required"),
65	            email: yup.string().trim().email("Invalid email format").required("Email is required"),
66	            password: yup.string().trim().min(8, "Password must be at least 8 characters").required(),
67	            role: yup.string().oneOf(['FM', 'Tenant', 'Staff']).required("Role is required"),
68	            tenantCode: yup.string().required("Access code is required")
69	        });
70	
71	        let validatedData = await validationSchema.validate(userData, { abortEarly: false });
72	
73	        // --- 3. THE SECURITY GATE ---
74	
75	        // BLOCK A: Prevent anyone from registering as FM publicly
76	        if (validatedData.role === 'FM') {
77	            return res.status(403).json({ errors: ["Administrative accounts cannot be created publicly."] });
78	        }
79	
80	        // BLOCK B: Tenant Registration (One-Time Invite Check)
81	        if (validatedData.role === 'Tenant') {
82	            const invite = await Invite.findOne({
83	                where: { code: validatedData.tenantCode, role: 'Tenant', isUsed: false }
84	            });
85	
86	            if (!invite) {
87	                return res.status(401).json({ errors: ["Invalid or used Invitation Code. Contact the FM office."] });
88	            }
89	
90	            // Check Expiration (e.g., 24h/48h set when invite was created)
91	            if (new Date() >= new Date(invite.expiresAt)) {
92	                return res.status(401).json({ errors: ["This invitation code has expired."] });
93	            }
94	
95	            // Mark invite as used so it cannot be used again
96	            await invite.update({ isUsed: true });
97	        }
98	
99	        // BLOCK C: Staff Registration (Hybrid Security Logic)
100	        if (validatedData.role === 'Staff') {
101	            const employer = await User.findOne({
102	                where: { role: 'Tenant', companyCode: validatedData.tenantCode }
103	            });
104	
105	            if (!employer) {
106	                return res.status(400).json({ errors: ["Invalid Unit Registration Code. Contact your manager."] });
107	            }
108	
109	            // Time Expiration Check (48 Hours)
110	            const fortyEightHours = 48 * 60 * 60 * 1000;
111	            const isExpired = Date.now() - new Date(employer.codeCreatedAt).getTime() > fortyEightHours;
112	
113	            if (isExpired) {
114	                return res.status(401).json({ errors: ["This unit code has expired (48h limit). Ask your manager to refresh it."] });
115	            }
116	
117	            // Usage Limit Check (Capacity)
118	            if (employer.codeCurrentUsage >= employer.codeMaxUsage) {
119	                return res.status(401).json({ errors: ["Registration capacity reached for this unit."] });
120	            }
121	
122	            // Link Staff to Tenant and increment usage
123	            validatedData.managerId = employer.id;
124	            await employer.increment('codeCurrentUsage');
125	        }
126	
127	        // 4. Hash & Save
128	        validatedData.password = await bcrypt.hash(validatedData.password, 10);
129	        let result = await User.create(validatedData);
130	
131	        res.json({ message: "Account registered successfully.", id: result.id });
132	
133	    } catch (err) {
134	        console.error("Registration Error Logic:", err);
135	        let errorMessages = [];
136	        if (err.name === 'SequelizeUniqueConstraintError') {
137	            errorMessages = ["This email is already registered in our system."];
138	        } else if (err.errors) {
139	            errorMessages = err.errors.map(e => (typeof e === 'object' ? e.message : e));
140	        } else {
141	            errorMessages = [err.message || "An unexpected system error occurred."];
142	        }
143	        res.status(400).json({ errors: errorMessages });
144	    }
145	});
