369	router.delete("/:id", verifyToken, async (req, res) => {
370	    try {
371	        const staffMember = await User.findByPk(req.params.id);
372	        if (!staffMember) return res.status(404).json({ message: "Not found." });
373	
374	        if (String(staffMember.id) === String(req.user.id)) {
375	            return res.status(400).json({ message: "Self-deletion is restricted. Ask another Facilities Manager to off-board this account." });
376	        }
377	
378	        const isFacilitiesManager = req.user.role === 'FM';
379	        const isTenantDeletingOwnStaff = req.user.role === 'Tenant' && staffMember.managerId === req.user.id;
380	
381	        if (!isFacilitiesManager && !isTenantDeletingOwnStaff) {
382	            return res.status(403).json({ message: "Unauthorized action." });
383	        }
384	
385	        // Tenant off-boarding guard: never leave orphan Staff. The FM must
386	        // remove or reassign the tenant's Staff before the tenant account
387	        // itself can be deleted (safest PoC behaviour → 409 Conflict).
388	        if (staffMember.role === 'Tenant') {
389	            const linkedStaff = await User.count({ where: { role: 'Staff', managerId: staffMember.id } });
390	            if (linkedStaff > 0) {
391	                return res.status(409).json({
392	                    message: `This tenant still has ${linkedStaff} linked Staff account(s). Remove or reassign them before off-boarding the tenant.`
393	                });
394	            }
395	        }
396	
397	        const targetId = staffMember.id;
398	        const targetName = staffMember.name;
399	
400	        // --- PDPA-COMPLIANT OFF-BOARDING (data minimisation, TRANSACTIONAL) ---
401	        // Every step commits together or not at all — no half-deleted accounts.
402	        await sequelize.transaction(async (t) => {
403	            // 1. Explicitly wipe the protected biometric template first, so it
404	            //    can never linger even if a later step fails and is retried.
405	            await staffMember.update({ faceVector: null, isEnrolled: false }, { transaction: t });
406	
407	            // 2. Hard-delete their attendance trail.
408	            await Attendance.destroy({ where: { userId: targetId }, transaction: t });
409	
410	            // 3. Anonymise — not delete — the security/access logs that referenced
411	            //    this person. The events stay for the security audit trail, but the
412	            //    personal linkage (name + matched user id) is stripped, and any
413	            //    description containing their name is replaced with a neutral one.
414	            await SecurityLog.update(
415	                { personnelName: null, matchedUserId: null },
416	                {
417	                    where: { [Op.or]: [{ personnelName: targetName }, { matchedUserId: targetId }] },
418	                    transaction: t
419	                }
420	            );
421	            await SecurityLog.update(
422	                { desc: 'Access event retained for audit — personnel record removed and identity anonymised.' },
423	                { where: { desc: { [Op.like]: `%${targetName}%` } }, transaction: t }
424	            );
425	
426	            // 4. Bookings keep their operational audit trail (ref, company,
427	            //    schedule, gate scans) but lose the personal account linkage.
428	            await Booking.update(
429	                { tenantId: null },
430	                { where: { tenantId: targetId }, transaction: t }
431	            );
432	
433	            // 5. Retire (never delete) any evaluation-participant mapping so
434	            //    the P-label stays reserved and historical evaluation records
435	            //    keep their meaning. userId becomes NULL via ON DELETE SET
436	            //    NULL when the User row is destroyed below.
437	            await retireEvaluationParticipant(targetId, t);
438	
439	            // 6. Hard-delete the user row itself.
440	            await staffMember.destroy({ transaction: t });
441	        });
442	
443	        // 4. Ask the AI service to reload its known-face cache so the wiped
444	        //    template disappears from memory immediately. NON-FATAL: the
445	        //    off-boarding already succeeded; the cache also reloads on restart.
446	        try {
447	            const faceAiUrl = process.env.FACE_AI_URL || 'http://127.0.0.1:8501';
448	            await axios.get(`${faceAiUrl}/refresh`, {
449	                timeout: 5000,
450	                headers: await aiServiceHeaders(faceAiUrl)
451	            });
