// original forgot-password contract (and its test).
const passwordResetLimiter = makeLimiter({
  windowMs: num(process.env.RATE_LIMIT_RESET_WINDOW_MS, 15 * MIN),
  max: num(process.env.RATE_LIMIT_RESET_MAX, 5),
  keyGenerator: ipKey,
});

