  windowMs: num(process.env.RATE_LIMIT_READ_WINDOW_MS, 1 * MIN),
  max: num(process.env.RATE_LIMIT_READ_MAX, 300),
  skipInternalService: true,
});

// Authenticated writes (create/update/delete). Moderate.
