1	// Frontend tests — route protection for facial/access pages (Felicia)
2	// Verifies unauthenticated and non-FM users cannot reach protected content.
3	import React from "react";
4	import { render, screen } from "@testing-library/react";
5	import { MemoryRouter } from "react-router-dom";
6	import { describe, test, expect, beforeEach } from "vitest";
7	
8	import ProtectedRoute from "../../src/components/ProtectedRoute";
9	
10	const Secret = () => <div>SECRET-DASHBOARD</div>;
11	
12	const renderGuarded = (props = {}) =>
13	  render(
14	    <MemoryRouter>
15	      <ProtectedRoute {...props}><Secret /></ProtectedRoute>
16	    </MemoryRouter>
17	  );
18	
19	beforeEach(() => localStorage.clear());
20	
21	describe("ProtectedRoute", () => {
22	  test("blocks access when no token is present", () => {
23	    renderGuarded();
24	    expect(screen.queryByText("SECRET-DASHBOARD")).toBeNull();
25	  });
26	
27	  test("blocks a non-FM user from an FM-only page", () => {
28	    localStorage.setItem("accessToken", "t");
29	    localStorage.setItem("userRole", "Staff");
30	    renderGuarded({ requiredRole: "FM" });
31	    expect(screen.queryByText("SECRET-DASHBOARD")).toBeNull();
32	  });
33	
34	  test("allows an FM user into an FM-only page", () => {
35	    localStorage.setItem("accessToken", "t");
36	    localStorage.setItem("userRole", "FM");
37	    renderGuarded({ requiredRole: "FM" });
38	    expect(screen.getByText("SECRET-DASHBOARD")).toBeTruthy();
39	  });
40	
41	  test("allowedRoles permits any listed role", () => {
42	    localStorage.setItem("accessToken", "t");
43	    localStorage.setItem("userRole", "Tenant");
44	    renderGuarded({ allowedRoles: ["FM", "Tenant"] });
45	    expect(screen.getByText("SECRET-DASHBOARD")).toBeTruthy();
46	  });
47	
