# FlowGuard frontend — Nginx reverse-proxy config (envsubst template).
#
# This file is copied to /etc/nginx/templates/default.conf.template; the
# official nginx image substitutes ${...} environment variables at container
# startup, so no backend URL is baked into the image or JavaScript bundle.
#
# Runtime environment variables on the Cloud Run frontend service:
#   PORT         — injected automatically by Cloud Run
#   BACKEND_HOST — hostname only of the Node backend Cloud Run service
#                  Example:
#                  flowguard-server-xxxxxxxxxx.asia-southeast1.run.app
#
# Same-origin architecture:
#   /api/*       -> Node backend
#   /user        -> Node backend
#   /user/*      -> Node backend
#   /users       -> React SPA page
#   everything else -> React SPA with index.html fallback
#
# The Python AI service remains private and is not proxied directly here.
# The browser sends AI-related requests to the Node backend, which performs
# JWT/RBAC checks and calls the AI service using service-to-service auth.

server {
    listen ${PORT};
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

    # Base64 webcam frames can be large; match the backend JSON limit.
    client_max_body_size 50m;

    gzip on;
    gzip_types
        text/css
        application/javascript
        application/json
        image/svg+xml;

    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    add_header Referrer-Policy "no-referrer" always;

    # ---- Node backend: /api/* ----
    location /api/ {
        proxy_pass https://${BACKEND_HOST};
        proxy_http_version 1.1;

        proxy_ssl_server_name on;
        proxy_ssl_name ${BACKEND_HOST};

        proxy_set_header Host ${BACKEND_HOST};
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Proto https;

        # AI inference requests can take longer than normal API requests.
        proxy_connect_timeout 30s;
        proxy_send_timeout 120s;
        proxy_read_timeout 120s;
    }

    # ---- Exact backend route: GET /user ----
    #
    # This exact match prevents Nginx from redirecting /user to /user/.
    # That redirect previously exposed the internal HTTP port and caused
    # the browser's mixed-content error.
    location = /user {
        proxy_pass https://${BACKEND_HOST};
        proxy_http_version 1.1;

        proxy_ssl_server_name on;
        proxy_ssl_name ${BACKEND_HOST};

        proxy_set_header Host ${BACKEND_HOST};
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Proto https;

        proxy_connect_timeout 30s;
        proxy_send_timeout 120s;
        proxy_read_timeout 120s;
    }

    # ---- Other backend user routes ----
    #
    # Examples:
    #   /user/login
    #   /user/register
    #   /user/manual-create
    #   /user/suspend/3
    #
    # This does not match the React page /users.
    location /user/ {
        proxy_pass https://${BACKEND_HOST};
        proxy_http_version 1.1;

        proxy_ssl_server_name on;
        proxy_ssl_name ${BACKEND_HOST};

        proxy_set_header Host ${BACKEND_HOST};
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Proto https;

        proxy_connect_timeout 30s;
        proxy_send_timeout 120s;
        proxy_read_timeout 120s;
    }

    # ---- Static assets: long cache for hashed build files ----
    location /assets/ {
        expires 30d;
        add_header Cache-Control "public, immutable";
        try_files $uri =404;
    }

    # ---- React Router SPA fallback ----
    #
    # Routes such as /users, /dashboard and /settings are served by React.
    location / {
        try_files $uri $uri/ /index.html;
    }
}

